from pathlib import Path
import subprocess,random,json,statistics,shutil
p=Path(__file__).parent;o=p/'screen';rng=random.Random(414109);raw=[];vs=['baseline','control','arrays','pivot','weighted','balanced']
for cc in ['gcc','native']:
 for n in [32,65535,65536,65537,500000]:
  for mode in range(11):
   checks=set()
   for rep in range(3):
    order=vs.copy();rng.shuffle(order)
    for v in order:
     active=o/'active';shutil.copyfile(o/f'{cc}-{v}',active);active.chmod(0o755);a=subprocess.run(['taskset','-c','12',str(active),str(n),str(mode),'1'],capture_output=True,text=True);assert a.returncode==0,(cc,n,mode,v,a.stderr);ns,s=map(int,a.stdout.split());checks.add(s);raw.append(dict(cc=cc,n=n,mode=mode,rep=rep,variant=v,ns=ns,checksum=s))
   assert len(checks)==1,(cc,n,mode,checks)
  print('screen',cc,n,flush=True)
(o/'raw.json').write_text(json.dumps(raw,indent=2));summary=[]
for cc,n,mode in sorted({(x['cc'],x['n'],x['mode'])for x in raw}):
 m={v:statistics.median(x['ns']for x in raw if(x['cc'],x['n'],x['mode'],x['variant'])==(cc,n,mode,v))for v in vs};summary.append(dict(cc=cc,n=n,mode=mode,median_ns=m,ratios={v:m[v]/max(m['baseline'],1)for v in m}))
(o/'summary.json').write_text(json.dumps(summary,indent=2));print('SCREEN DONE',len(raw),flush=True)

