from pathlib import Path
import subprocess,json,random,statistics,shutil,resource,time,hashlib
p=Path(__file__).parent;o=p/'main';official=Path('/tmp/lis_round2_20261030/official');extra=json.loads((p/'extras/metadata.json').read_text());cases=[dict(path=str(f),name=f.stem,official=True)for f in sorted((official/'in').glob('*.in'))]+[dict(x,official=False)for x in extra];vs=['baseline','control','pivot','masked'];raw=[];rng=random.Random(9414109)
for cc in ['gcc','native']:
 for case in cases:
  inp=Path(case['path']);checks=set()
  for rep in range(5):
   order=vs.copy();rng.shuffle(order)
   for v in order:
    active=o/'active';shutil.copyfile(o/f'{cc}-{v}',active);active.chmod(0o755);out=o/'active.out';before=resource.getrusage(resource.RUSAGE_CHILDREN);t=time.perf_counter_ns()
    with inp.open('rb')as fi,out.open('wb')as fo:a=subprocess.run(['taskset','-c','12',str(active)],stdin=fi,stdout=fo,stderr=subprocess.PIPE)
    wall=time.perf_counter_ns()-t;after=resource.getrusage(resource.RUSAGE_CHILDREN);cpu=round((after.ru_utime+after.ru_stime-before.ru_utime-before.ru_stime)*1e9);assert a.returncode==0,a.stderr;h=hashlib.sha256(out.read_bytes()).hexdigest();checks.add(h)
    if rep==0:
     if case['official']:
      check=subprocess.run(['taskset','-c','4',str(official/'checker'),str(inp),str(out),str(official/'out'/f'{inp.stem}.out')],capture_output=True,text=True);assert check.returncode==0,(cc,inp,v,check.stderr)
     else:
      a=list(map(int,inp.read_text().split()))[1:];ans=list(map(int,out.read_text().split()));assert ans[0]==case['length']and len(ans)==ans[0]+1;ix=ans[1:];assert all(0<=k<len(a)for k in ix)and all(x<y and a[x]<a[y]for x,y in zip(ix,ix[1:]))
    raw.append(dict(cc=cc,case=case['name'],official=case['official'],rep=rep,variant=v,cpu_ns=cpu,wall_ns=wall,stdout_sha256=h))
  assert len(checks)==1,(cc,case,checks)
 print('main measured',cc,flush=True)
(o/'raw.json').write_text(json.dumps(raw,indent=2));out=[]
for cc,case,official_flag in sorted({(x['cc'],x['case'],x['official'])for x in raw}):
 m={v:statistics.median(x['cpu_ns']for x in raw if(x['cc'],x['case'],x['variant'])==(cc,case,v))for v in vs};w={v:statistics.median(x['wall_ns']for x in raw if(x['cc'],x['case'],x['variant'])==(cc,case,v))for v in vs};out.append(dict(cc=cc,case=case,official=official_flag,median_cpu_ns=m,median_wall_ns=w,ratios={v:m[v]/max(m['baseline'],1)for v in vs}))
(o/'summary.json').write_text(json.dumps(out,indent=2));print('MAIN DONE',len(raw),flush=True)

