    auto previous = std::make_unique_for_overwrite<Index[]>(v.size());
    tails.reserve(std::min(v.size(), std::size_t{64}));
#ifndef SKIP_RUNTIME_CHECKS
    reinsirk::detail::check_lis_value(v[0]);
#endif
