#endif
        if (Strict ? v[tails.back()] < v[i] : !(v[i] < v[tails.back()])) {
            previous[i] = tails.back();
            tails.push_back(static_cast<Index>(i));
            continue;
        }
        if (Strict ? !(v[tails.front()] < v[i]) : v[i] < v[tails.front()]) {
            tails.front() = static_cast<Index>(i);
            continue;
        }
        std::size_t lo = 1, count = tails.size() - 2;
        while (count != 0) {
            const auto half = count / 2;
            const auto mid = lo + half;
            const bool before = Strict ? v[tails[mid]] < v[i] : !(v[i] < v[tails[mid]]);
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
        previous[i] = tails[lo - 1];
        tails[lo] = static_cast<Index>(i);
    }
    std::vector<std::size_t> result(tails.size());
    auto at = tails.back();
    for (auto i = result.size(); i > 1; --i) {
        result[i - 1] = at;
        at = previous[at];
    }
    result[0] = at;
    return result;
}
#if defined(__GNUC__) && !defined(__clang__) && __GNUC__ == 15 && __GNUC_MINOR__ == 2 && defined(__x86_64__)
template <class Index>
std::vector<std::size_t> LISIndicesCached(const std::vector<std::int64_t>& v) {
    if (v.empty()) return {};
    std::size_t capacity = std::min(v.size(), std::size_t{64}), length = 1;
    auto tails = std::make_unique_for_overwrite<Index[]>(capacity);
    auto values = std::make_unique_for_overwrite<std::int64_t[]>(capacity);
    auto previous = std::make_unique_for_overwrite<Index[]>(v.size());
    tails[0] = 0;
    values[0] = v[0];
    const auto grow = [&]<bool KeepValues>() {
        const auto next_capacity = capacity + std::min(capacity, v.size() - capacity);
        if constexpr (KeepValues) {
            auto next_values = std::make_unique_for_overwrite<std::int64_t[]>(next_capacity);
            std::copy_n(values.get(), length, next_values.get());
            values = std::move(next_values);
        }
        auto next_tails = std::make_unique_for_overwrite<Index[]>(next_capacity);
        std::copy_n(tails.get(), length, next_tails.get());
        tails = std::move(next_tails);
        capacity = next_capacity;
    };
    std::size_t i = 1;
    for (; i < v.size(); ++i) {
        const auto value = v[i];
        if (values[length - 1] < value) {
            previous[i] = tails[length - 1];
            if (length == capacity) grow.template operator()<true>();
            values[length] = value;
            tails[length++] = static_cast<Index>(i);
            if (length >= 4096 && length > (i + 1) / 4) { ++i; break; }
            continue;
        }
        if (!(values[0] < value)) {
            tails[0] = static_cast<Index>(i);
            values[0] = value;
            continue;
        }
        std::size_t lo = 1, count = length - 2;
        if (count <= 4096) {
            while (count >= 32) {
                const auto quarter = count / 4;
                const auto p0 = lo + quarter, p1 = p0 + quarter, p2 = p1 + quarter;
                const bool b0 = values[p0] < value, b1 = values[p1] < value, b2 = values[p2] < value;
                const auto left = b0 ? p0 + 1 : lo;
                const auto right = b2 ? p2 + 1 : p1 + 1;
                lo = b1 ? right : left;
                count = quarter - static_cast<std::size_t>(b0) + (b2 ? count % 4 : 0);
            }
        }
        while (count != 0) {
            const auto half = count / 2, mid = lo + half;
            const bool before = values[mid] < value;
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
        previous[i] = tails[lo - 1];
        tails[lo] = static_cast<Index>(i);
        values[lo] = value;
    }
    values.reset();
    for (; i < v.size(); ++i) {
        const auto value = v[i];
        if (v[tails[length - 1]] < value) {
            previous[i] = tails[length - 1];
            if (length == capacity) grow.template operator()<false>();
            tails[length++] = static_cast<Index>(i);
            continue;
        }
        if (!(v[tails[0]] < value)) {
            tails[0] = static_cast<Index>(i);
            continue;
        }
        std::size_t lo = 1, count = length - 2;
        while (count != 0) {
            const auto half = count / 2, mid = lo + half;
            const bool before = v[tails[mid]] < value;
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
        previous[i] = tails[lo - 1];
        tails[lo] = static_cast<Index>(i);
    }
    std::vector<std::size_t> result(length);
    auto at = tails[length - 1];
    for (auto j = result.size(); j > 1; --j) {
        result[j - 1] = at;
        at = previous[at];
    }
    result[0] = at;
    return result;
}
#endif
