            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
        if (lo != 0 && lo != length) ++searches;
        tails[lo] = v[i];
        length += lo == length;
    }
    if (length >= 16 && length <= 64 && searches >= 128) return 1;
