template <bool Strict, class Index, class T>
std::vector<std::size_t> LISIndicesSelected(const std::vector<T>& v) {
    if constexpr (sizeof(Index) < sizeof(std::size_t) && std::is_arithmetic_v<T> && sizeof(T) <= 8 && !std::is_same_v<T,bool>) {
